<template>
  <view class="doctor-schedule">
    <view class="header">
      <text class="title">我的排班</text>
      <view class="date-selector">
        <view 
          v-for="(day, index) in weekDays" 
          :key="index" 
          class="date-item" 
          :class="{ active: currentDateIndex === index }"
          @click="selectDate(index)"
        >
          <text class="day">{{ day.dayOfWeek }}</text>
          <text class="date">{{ day.date }}</text>
        </view>
      </view>
    </view>
    
    <view class="schedule-list">
      <view v-if="schedules.length === 0" class="empty-tip">
        <text>当日无排班</text>
      </view>
      <view v-else v-for="(item, index) in schedules" :key="index" class="schedule-card">
        <view class="schedule-info">
          <view class="time-room">
            <text class="time">{{ item.timeSlot }}</text>
            <text class="room">诊室: {{ item.roomNumber }}</text>
          </view>
          <view class="patient-count">
            <text class="booked">已挂号: {{ item.bookedCount }}</text>
            <text class="total">总号源: {{ item.totalCount }}</text>
          </view>
          <view class="status" :class="getStatusClass(item)">
            <text>{{ getStatusText(item) }}</text>
          </view>
        </view>
      </view>
    </view>
    
    <view class="apply-btn-container">
      <button class="apply-btn" @click="goToApplyChange">申请调班</button>
    </view>
    
    <view class="tab-bar">
      <view class="tab-item" @click="goToPatientList">
        <image class="tab-icon" src="/static/patient.png" mode="aspectFit"></image>
        <text class="tab-text">患者详情</text>
      </view>
      <view class="tab-item" @click="goToProfile">
        <image class="tab-icon" src="/static/doctor.png" mode="aspectFit"></image>
        <text class="tab-text">个人信息</text>
      </view>
    </view>
  </view>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue';
import { uniNavigateTo } from '@/utils/uniHelper';

// 生成未来7天的日期
const generateWeekDays = () => {
  const days = [];
  const dayNames = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];
  
  for (let i = 0; i < 7; i++) {
    const date = new Date();
    date.setDate(date.getDate() + i);
    days.push({
      date: `${date.getMonth() + 1}/${date.getDate()}`,
      fullDate: date.toISOString().split('T')[0],
      dayOfWeek: dayNames[date.getDay()]
    });
  }
  return days;
};

const weekDays = ref(generateWeekDays());
const currentDateIndex = ref(0);
const schedules = ref([]);

// 模拟数据 - 实际应用中应从API获取
const fetchSchedules = (dateIndex) => {
  // 模拟API调用
  setTimeout(() => {
    if (dateIndex === 0) {
      schedules.value = [
        { 
          id: 1, 
          date: weekDays.value[dateIndex].fullDate, 
          timeSlot: '上午 8:00-11:30', 
          roomNumber: 'A-101', 
          bookedCount: 15, 
          totalCount: 20 
        },
        { 
          id: 2, 
          date: weekDays.value[dateIndex].fullDate, 
          timeSlot: '下午 14:00-17:30', 
          roomNumber: 'A-102', 
          bookedCount: 8, 
          totalCount: 20 
        }
      ];
    } else if (dateIndex === 1) {
      schedules.value = [
        { 
          id: 3, 
          date: weekDays.value[dateIndex].fullDate, 
          timeSlot: '上午 8:00-11:30', 
          roomNumber: 'B-201', 
          bookedCount: 5, 
          totalCount: 20 
        }
      ];
    } else if (dateIndex === 2) {
      schedules.value = [];
    } else {
      schedules.value = [
        { 
          id: 4, 
          date: weekDays.value[dateIndex].fullDate, 
          timeSlot: '下午 14:00-17:30', 
          roomNumber: 'A-103', 
          bookedCount: 12, 
          totalCount: 15 
        }
      ];
    }
  }, 300);
};

const selectDate = (index) => {
  currentDateIndex.value = index;
  fetchSchedules(index);
};

const getStatusText = (item) => {
  const remaining = item.totalCount - item.bookedCount;
  if (remaining === 0) return '已满';
  if (remaining <= 5) return '紧张';
  return '充足';
};

const getStatusClass = (item) => {
  const remaining = item.totalCount - item.bookedCount;
  if (remaining === 0) return 'full';
  if (remaining <= 5) return 'tight';
  return 'available';
};

const goToApplyChange = () => {
  uniNavigateTo({ url: '/pages/doctor/schedule/apply-change' });
};

const goToPatientList = () => {
  uniNavigateTo({ url: '/pages/doctor/patients/patient-list' });
};

const goToProfile = () => {
  uniNavigateTo({ url: '/pages/doctor/profile/doctor-profile' });
};

onMounted(() => {
  fetchSchedules(0);
});
</script>

<style scoped>
.doctor-schedule {
  min-height: 100vh;
  background-color: #f5f7fa;
  padding-bottom: 120rpx;
}

.header {
  background-color: #1677ff;
  padding: 40rpx 30rpx;
  color: #fff;
}

.title {
  font-size: 36rpx;
  font-weight: bold;
  margin-bottom: 30rpx;
}

.date-selector {
  display: flex;
  overflow-x: auto;
  padding-bottom: 10rpx;
}

.date-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-right: 30rpx;
  padding: 16rpx 24rpx;
  border-radius: 12rpx;
  background-color: rgba(255, 255, 255, 0.2);
}

.date-item.active {
  background-color: #fff;
}

.date-item.active .day,
.date-item.active .date {
  color: #1677ff;
}

.day {
  font-size: 24rpx;
  margin-bottom: 6rpx;
}

.date {
  font-size: 28rpx;
  font-weight: 500;
}

.schedule-list {
  padding: 30rpx;
}

.empty-tip {
  text-align: center;
  padding: 100rpx 0;
  color: #999;
  font-size: 28rpx;
}

.schedule-card {
  background-color: #fff;
  border-radius: 16rpx;
  padding: 30rpx;
  margin-bottom: 20rpx;
  box-shadow: 0 2rpx 10rpx rgba(0, 0, 0, 0.05);
}

.schedule-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.time-room {
  flex: 1;
}

.time {
  font-size: 32rpx;
  font-weight: bold;
  color: #333;
  display: block;
  margin-bottom: 10rpx;
}

.room {
  font-size: 26rpx;
  color: #666;
}

.patient-count {
  flex: 1;
  text-align: center;
}

.booked, .total {
  display: block;
  font-size: 26rpx;
  color: #666;
  margin-bottom: 6rpx;
}

.status {
  width: 120rpx;
  height: 60rpx;
  border-radius: 30rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26rpx;
}

.status.available {
  background-color: #e6f7ff;
  color: #1677ff;
}

.status.tight {
  background-color: #fff7e6;
  color: #fa8c16;
}

.status.full {
  background-color: #fff1f0;
  color: #f5222d;
}

.apply-btn-container {
  padding: 30rpx;
}

.apply-btn {
  background-color: #1677ff;
  color: #fff;
  height: 88rpx;
  line-height: 88rpx;
  border-radius: 44rpx;
  font-size: 30rpx;
}

.tab-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 110rpx;
  background-color: #fff;
  display: flex;
  box-shadow: 0 -2rpx 10rpx rgba(0, 0, 0, 0.05);
}

.tab-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.tab-icon {
  width: 48rpx;
  height: 48rpx;
  margin-bottom: 6rpx;
}

.tab-text {
  font-size: 24rpx;
  color: #333;
}
</style>